@font-face{font-family:"Playfair";src:url(data:font/ttf;base64,) format("truetype");font-weight:400 900;font-display:block;}
@font-face{font-family:"Mont";src:url(data:font/ttf;base64,) format("truetype");font-weight:400 900;font-display:block;}
/* Shared base for the premium posters: real embedded display fonts + social-icon system.
   Each poster file brings its OWN distinct layout CSS; this only provides fonts + icons + resets. */
:root { --brand-primary:#0F3D5E; --brand-accent:#D4970F; --brand-ink:#0B1B2B; --brand-bg:#F7F5F0; }
* { margin:0; padding:0; box-sizing:border-box; }
html,body { width:1080px; height:1350px; overflow:hidden; }
body { font-family:"Mont","Segoe UI",system-ui,sans-serif; -webkit-font-smoothing:antialiased; }
.serif { font-family:"Playfair",Georgia,serif; }

.poster { position:relative; width:1080px; height:1350px; overflow:hidden; }
.ph { background-size:cover; background-position:center; background-repeat:no-repeat; }

/* logo lockup (constant across all three) */
.logo { display:flex; align-items:center; gap:16px; }
.logo img { height:84px; width:auto; border-radius:20px; box-shadow:0 8px 22px rgba(0,0,0,.3); }
.logo .wordmark { font-family:"Playfair",serif; font-weight:700; font-size:38px; }

/* social CTA row */
.social { display:flex; align-items:center; gap:16px; }
.social .chip { display:inline-flex; align-items:center; gap:12px; font-weight:600; font-size:26px; white-space:nowrap; }
.social .ic { width:52px; height:52px; border-radius:50%; display:grid; place-items:center; flex:0 0 auto; }
.social .ic svg { width:28px; height:28px; display:block; }
.social .ic.wa { background:#25D366; color:#fff; }
.social .ic.fb { background:#1877F2; color:#fff; }
.social .ic.x  { background:#000; color:#fff; }
.social .ic.ghost { background:rgba(255,255,255,.14); border:1px solid rgba(255,255,255,.3); color:#fff; }
